func TestRing_Concurrent(t *testing.T) {
	r, _ := NewRing(50)
	var wg sync.WaitGroup

	// Writer goroutines
	for range 10 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 100 {
				slog.New(r).Info("concurrent")
			}
		}()
	}

	// Reader goroutines
	for range 5 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 50 {
				_ = r.Records()
			}
		}()
	}

	wg.Wait()

	recs := r.Records()
	if len(recs) != 50 {
		t.Logf("ring should have 50 records (full), got %d", len(recs))
	}
}

